-- Baseline: the schema as it was created by hand in the Supabase dashboard
-- for the 2025 tournament. Exported from the live project on 2026-10-10.
-- Later changes go into new migrations; do not edit this file.

create type public.class as enum ('Schüler', 'T-Ball');

create type public.location as enum ('Halle 1', 'Halle 2', 'Halle 3', 'Essensraum');

create type public.team as enum (
  'Karlsruhe',
  'Darmstadt 1',
  'Darmstadt 2',
  'Remchingen',
  'Bretten',
  'Bretten 1',
  'Bretten 2',
  'Stuttgart 1',
  'Stuttgart 2',
  'Nagold',
  'Mannheim',
  'Schriesheim',
  'Herrenberg',
  'Heidelberg'
);

-- Schedule and results. A row with eventname set is a non-game event
-- (e.g. "Siegerehrung") and has no teams or scores.
create table public.games (
  id bigint generated by default as identity primary key,
  hometeam text,
  awayteam text,
  location public.location not null,
  homescore smallint,
  awayscore smallint,
  time time without time zone not null,
  class public.class not null,
  scorer text,
  eventname text,
  constraint games_id_key unique (id)
);

-- Hand-maintained standings. Position "A1", "B2", ... = group table,
-- "1", "01", ... = overall ranking. Replaced by computed standings (ADR-0006).
create table public.standings (
  id bigint generated by default as identity primary key,
  position text not null default '0',
  team public.team not null,
  class public.class not null,
  wins smallint not null default 0,
  losses smallint not null default 0,
  diff real not null default 0
);

create table public.items (
  id bigint generated by default as identity primary key,
  category text not null,
  item text not null,
  price real not null,
  "soldOut" boolean not null default false
);
comment on table public.items is 'items to sell';

-- answer may contain a small subset of HTML (ADR-0008).
create table public.faq (
  id bigint generated by default as identity primary key,
  question text not null,
  answer text not null
);

-- Public read-only access (ADR-0004). No write policies: writes only via
-- the dashboard / service role.
alter table public.games enable row level security;
alter table public.standings enable row level security;
alter table public.items enable row level security;
alter table public.faq enable row level security;

create policy "Enable read access for all users" on public.games
  for select to public using (true);
create policy "Enable read access for all users" on public.standings
  for select to public using (true);
create policy "Enable read access for all users" on public.items
  for select to public using (true);
create policy "Enable read access for all users" on public.faq
  for select to public using (true);

-- Live updates for all tables the app subscribes to.
alter publication supabase_realtime
  add table public.games, public.standings, public.items, public.faq;
